-- re-runs are free and existing (edited) rows are never clobbered.
INSERT OR IGNORE INTO journal_chapters (id, day_date, title, voice, body, threads, closer, public, sort) VALUES ('ch00-two-pints', '2026-08-14', 'The Upgrade Text', 'the weather vane finally boards a plane', '[{"t":"map","focus":"london","by":"seed"},{"t":"p","text":"The text landed at Changi: upgraded. An A380, which means Business is upstairs. Nobody turns left. You climb.","by":"seed"},{"t":"p","text":"Twenty-six hours out of Saigon, and suddenly the flight was the holiday.","by":"seed"},{"t":"p","text":"By six that evening: a pub off Kensington High Street. Two pints. No plan past the word \"Europe\".","by":"seed"},{"t":"p","text":"Then the map started talking. I had checked nineteen forecasts before the second pint arrived — Claire timed me. The trip drew itself anyway. It turned out right about nearly everything, and wrong about all the best bits.","by":"seed"},{"t":"doctrine","text":"plans you make argue with you. this one just turned up.","by":"seed"},{"t":"prompt","q":"Which pub, and whose pint was the map drawn on?","by":"seed"},{"t":"prompt","q":"What did the upgrade actually buy — the seat or the sleep?","by":"seed"},{"t":"prompt","q":"What was the first port either of us said out loud?","by":"seed"},{"t":"mono","text":"Marriott Kensington, one night, checked in at nine in the morning like civilised people","by":"seed"},{"t":"card","star":"upstairs, not left","lines":[],"by":"seed"}]', '["doctrine","ledger","hardship"]', 'conditions remain grim', 0, 10);
INSERT OR IGNORE INTO journal_chapters (id, day_date, title, voice, body, threads, closer, public, sort) VALUES ('ch01-gare-du-nord', '2026-08-15', 'Missed It by a Minute', 'three men, one lanyard, and the 17:56 leaving without us', '[{"t":"map","focus":"paris","by":"seed"},{"t":"p","text":"One minute. That is what three men and a lanyard cost us.","by":"seed"},{"t":"p","text":"The 13:31 out of St Pancras did what it always does: made France feel like a suburb. At 16:49 we hit Gare du Nord with eighty kilos of luggage and seventy minutes to cross town for the 17:56 to Lyon.","by":"seed"},{"t":"p","text":"At the métro barriers a man wearing a lanyard explained that he worked there. He did not. Two colleagues of his arranged themselves behind us.","by":"seed"},{"t":"p","text":"There followed a short conversation, in two languages, about whether our tickets and bags required his assistance. They did not. Claire was behind me the whole time.","by":"seed"},{"t":"p","text":"The tickets stayed where they were. The three gentlemen went off to find easier company. We missed the 17:56 — the part I am still filing paperwork about.","by":"seed"},{"t":"prompt","q":"What did the lanyard actually look like?","by":"seed"},{"t":"prompt","q":"What was said to the two behind us, and in which language?","by":"seed"},{"t":"p","text":"The pré-plainte went in online that evening. Four attachments. The French state received our account with the administrative warmth of a toll booth.","by":"seed"},{"t":"p","text":"The 19:00 took us to Lyon instead — a city neither of us had planned to sleep in. The kind of navigational error you would pay money for. In a sense, we had.","by":"seed"},{"t":"ledger","amount":"981 GBP","text":"Eurostar Premier, coach 12, the seats that did their job","by":"seed"},{"t":"ledger","amount":"148 EUR","text":"the 19:00 to Lyon, bought at 18:16, gate still open","by":"seed"},{"t":"ledger","amount":"0 EUR","text":"the pré-plainte, filed online, four attachments","by":"seed"},{"t":"doctrine","text":"avoid ruin, then optimise. lived, that evening, in exactly that order.","by":"seed"},{"t":"prompt","q":"What went into the pré-plainte as evidence?","by":"seed"},{"t":"card","star":"the tickets stayed where they were","lines":[],"by":"seed"}]', '["screens","ledger","hardship"]', 'for a minute there, conditions were grim', 0, 20);
INSERT OR IGNORE INTO journal_chapters (id, day_date, title, voice, body, threads, closer, public, sort) VALUES ('ch02-lyon-caught-us', '2026-08-16', 'The City That Caught Us', 'nobody had planned any of this, which is why it worked', '[{"t":"map","focus":"lyon","by":"seed"},{"t":"p","text":"We woke up in a city neither of us had chosen. That is an unusual way to meet one. Nothing promised, so nothing owed.","by":"seed"},{"t":"p","text":"The hotel used to be the Hôtel Dieu, a hospital from the seventeenth century, and they kept the bones. Corridors wide enough for stretchers. A dome built for last rites, now dispensing breakfast — same mission of making people feel better, revised pricing.","by":"seed"},{"t":"p","text":"By mid-morning Lyon was baking properly, the stone handing the heat back with interest. We retreated into the Halles Paul Bocuse: a city that decided its market deserved a roof and its greatest cook''s name over the door. We laid in provisions with the seriousness of people who had no plan to serve them.","by":"seed"},{"t":"prompt","q":"What came home from Halles Paul Bocuse and what got eaten standing up?","by":"seed"},{"t":"p","text":"Towards evening we took la ficelle up to Fourvière. The funicular. Two minutes of gradient the city stopped noticing sometime last century.","by":"seed"},{"t":"drop","text":"The string has been hauling Lyon up its own hill since 1862, and the town is so unimpressed it named it after kitchen twine. What does a city have to see before a hundred and sixty years of not falling counts as showing off?","by":"seed"},{"t":"p","text":"At the top: terraces, the whole city laid out under them, both rivers, the roofs going pink. Also a bottle of champagne that was not going to survive another day of that heat. It had to be dealt with on the spot, and we would like it minuted that we objected.","by":"seed"},{"t":"p","text":"Sunset was 20:46 and it ran on time — more than can be said for the service that delivered us here in the first place. Conditions, in short, remained grim.","by":"seed"},{"t":"prompt","q":"What was the champagne on the Fourvière terrace?","by":"seed"},{"t":"doctrine","text":"\"Nobody is required to tell the planned city what the unplanned one did.\"","by":"seed"},{"t":"p","text":"Somewhere between the market and the bottle it was settled: we were not leaving in the morning. Nobody remembers a vote being held.","by":"seed"},{"t":"prompt","q":"Who decided Lyon deserved the second night, and when?","by":"seed"},{"t":"card","star":"A bottle over both rivers at 20:46, in a city that caught us.","lines":[],"by":"seed"}]', '["drops","doctrine","hardship"]', 'the hardship continues', 0, 30);
INSERT OR IGNORE INTO journal_chapters (id, day_date, title, voice, body, threads, closer, public, sort) VALUES ('ch03-fourteen-degrees', '2026-08-17', 'Fourteen Degrees in the Caveau', 'Côte-Rôtie, Condrieu, and a mountain we declined to see badly', '[{"t":"map","focus":"lyon","by":"seed"},{"t":"p","text":"Fourteen degrees. The coolest room in France that week was a wine cellar, and we were in it.","by":"seed"},{"t":"p","text":"We had a driver for the day. Somebody has to stay sober in the northern Rhône, and it was not going to be either of us.","by":"seed"},{"t":"p","text":"South of Lyon the valley narrows and the vineyards stop pretending to be agriculture. Terraces stacked up slopes you would want a rope for in any other context. Côte-Rôtie above Ampuis on one side, Condrieu a few bends further on. It has run this way for about two thousand years. The theory: face the hill at the sun hard enough and the wine forgives the labour.","by":"seed"},{"t":"drop","text":"The roasted slope, named by people who stood on it in August and knew exactly what they were describing. Who carried the first stones up?","by":"seed"},{"t":"p","text":"Guigal''s Caveau du Château holds fourteen degrees. In a normal year that is a technical note about storage. That week it was the main event, by a wide margin. Conditions were grim.","by":"seed"},{"t":"p","text":"There is a version of this day where I explain what Viognier does at cellar temperature. Instead: we went quiet in there. We stayed as long as the tasting could reasonably be stretched, then a bit longer, and bottles were involved by the exit.","by":"seed"},{"t":"prompt","q":"Which bottle came back from the Caveau?","by":"seed"},{"t":"ledger","amount":"","text":"— bottles from the Caveau, count unrecorded","by":"seed"},{"t":"p","text":"Mont Blanc had been sitting at the end of the plan, the way it sits at the end of every plan in that part of the world. Somewhere in that day it came off the sheet. Not cancelled. Deferred. In this family that is a different word entirely, with its own file.","by":"seed"},{"t":"prompt","q":"Where exactly were we standing when Mont Blanc got deferred?","by":"seed"},{"t":"doctrine","text":"I won''t watch cams… Oppenheimer in 70mm","by":"seed"},{"t":"prompt","q":"What was the 70mm line a reply to?","by":"seed"},{"t":"p","text":"The mountain is not going anywhere. The driver took us back up the valley into the August, which had not improved.","by":"seed"}]', '["doctrine","drops","ledger"]', 'we press on', 0, 40);
INSERT OR IGNORE INTO journal_chapters (id, day_date, title, voice, body, threads, closer, public, sort) VALUES ('ch04-the-1140', '2026-08-18', 'The 11:40 to Nice', 'via Marseille, a seaview at the end of it', '[{"t":"map","focus":"nice","by":"seed"},{"t":"p","text":"The 11:40 went south. That is all we asked of it. For once the plan and the timetable were the same document.","by":"seed"},{"t":"p","text":"One change at Marseille. Reads harmlessly on a booking confirmation; involves rather more luggage in person. We made the second train with time to spare, which after Paris felt like showing off.","by":"seed"},{"t":"prompt","q":"What did Marseille look like from the platform?","by":"seed"},{"t":"mono","text":"TKD3G6 / BL4P7Q / HPW6G9 — three references, two trains, zero negotiations at any barrier.","by":"seed"},{"t":"p","text":"Out of Marseille the sea turned up on the right-hand side and stayed there the rest of the way. The whole coast ran alongside the train like it had nothing better to do. Nobody charges extra for that yet, though give them time.","by":"seed"},{"t":"p","text":"Hotel Suisse is on Quai Rauba Capeù — Niçois rather than French, and nobody needs to pronounce it correctly to be let in. The lift was small. The room was not.","by":"seed"},{"t":"p","text":"Then I opened the shutters. The entire Baie des Anges was in the window — the full bay, blue out to the horizon. I noted for the record that conditions had deteriorated further and were now frankly unreasonable.","by":"seed"},{"t":"prompt","q":"What could you see when the shutters opened?","by":"seed"},{"t":"ledger","amount":"880 AUD","text":"Hotel Suisse, the seaview, breakfast","by":"seed"},{"t":"p","text":"The seaview was itemised on the invoice. Correct procedure — hardship at that level should always be receipted. Breakfast was included, so no prospect of the situation improving before mid-morning at the earliest.","by":"seed"},{"t":"p","text":"We had come a long way for water. The water turned up in bulk, on schedule, directly below the window.","by":"seed"},{"t":"p","text":"Somewhere down the hill that evening there was a first dinner in Nice. That is exactly where the record goes thin.","by":"seed"},{"t":"prompt","q":"First dinner in Nice — where, and who chose?","by":"seed"},{"t":"card","star":"The shutters, and what was behind them.","lines":[],"by":"seed"}]', '["water","ledger","hardship"]', 'no relief in sight', 0, 50);
INSERT OR IGNORE INTO journal_chapters (id, day_date, title, voice, body, threads, closer, public, sort) VALUES ('ch05-the-last-berth', '2026-08-19', 'The Last Berth', 'booked Monday, boarded Wednesday, sailed at six', '[{"t":"map","focus":"nice","by":"seed"},{"t":"p","text":"The water had no business being that colour.","by":"seed"},{"t":"p","text":"Last morning ashore, so we spent it at the beach. Claire progressed the tan. I conducted a full review of the sand — ordinary sand, doing ordinary sand things.","by":"seed"},{"t":"p","text":"Conditions overall remained grim. Sun, salt, nothing required of anyone until four.","by":"seed"},{"t":"p","text":"The ship had been booked two days out, on one of the last berths going. Not the recommended run-up to ten nights at sea. Exactly the run-up we used.","by":"seed"},{"t":"p","text":"Two days is roughly the window between finding out a thing exists and watching somebody else get it. We have run that analysis before. The decision took about as long as it deserved.","by":"seed"},{"t":"doctrine","text":"\"When the right asset shows up late, the answer is still yes.\"","by":"seed"},{"t":"ledger","amount":"23,280 AUD","text":"the ship, ten nights, all of it","by":"seed"},{"t":"mono","text":"Le Dumont d''Urville · boarding 16:00 · sail 18:00 · Cabin 306, Deck 3","by":"seed"},{"t":"p","text":"At 16:00 we boarded Le Dumont d''Urville. 184 passengers, 92 staterooms, 118 crew — better than one crew member for every two of us. I checked the ratio twice and elected not to argue with it.","by":"seed"},{"t":"p","text":"Cabin 306, Deck 3. The balcony sat close enough to the water that the water stopped being a view — it became a fitting of the room, part of the joinery, present at all hours.","by":"seed"},{"t":"prompt","q":"When did we know 306 was the right cabin?","by":"seed"},{"t":"ledger","amount":"400 EUR","text":"Virtuoso credit, to be spent aboard, fate unrecorded","by":"seed"},{"t":"prompt","q":"What did the €400 Virtuoso credit become?","by":"seed"},{"t":"p","text":"She sailed at 18:00. Nice went off the stern slowly, the beach we had audited that morning included.","by":"seed"},{"t":"p","text":"The arithmetic was pleasing. Morning on the sand, evening at sea, nothing owed anywhere in between. Ten nights of this lay ahead, and I want it recorded that we faced them without complaint.","by":"seed"},{"t":"prompt","q":"Where were we standing when she sailed?","by":"seed"},{"t":"card","star":"Nice off the stern from the balcony of 306","lines":[],"by":"seed"}]', '["ledger","doctrine","hardship"]', 'morale remains low', 0, 60);
INSERT OR IGNORE INTO journal_chapters (id, day_date, title, voice, body, threads, closer, public, sort) VALUES ('ch06-calvi', '2026-08-20', 'The Citadel from the Water', 'first tender, first walking tour, Nelson''s worst day', '[{"t":"map","focus":"calvi","by":"seed"},{"t":"p","text":"Walls first. Out of the water, straight up, until they filled every window on the boat.","by":"seed"},{"t":"p","text":"First tender of the trip. The ship anchors off. Everyone files down to sea level and goes ashore in a boat the size of a bus. The whole arrangement exists so the citadel can do its trick. Whoever put those walls there wanted them judged from exactly where we were sitting, and I can report the judging went well.","by":"seed"},{"t":"prompt","q":"What did Claire photograph from the tender?","by":"seed"},{"t":"p","text":"Ashore, the included walking tour. Included in the sense that we had already paid for it and were therefore going. A guide took us up into the citadel on cobbles worn somewhere past marble, under a sun also included at no additional cost.","by":"seed"},{"t":"p","text":"Conditions, in short, remained grim. We soldiered up through the gateways with the rest of the tender, single file where the walls insisted on it.","by":"seed"},{"t":"prompt","q":"What did the guide say that survived the day?","by":"seed"},{"t":"drop","text":"Nelson lost the sight of his right eye besieging these walls in 1794. We had the same walls in front of us and both eyes working, so what would he have called a fair price for the view?","by":"seed"},{"t":"p","text":"Below the ramparts the water was doing what Corsican water is contracted to do. That raised the only real question of the afternoon.","by":"seed"},{"t":"p","text":"The fork in the day was the Revellata snorkel. €150 a head, optional — and €150 a head is where optional stops being a word and becomes a position. One side of the fork: the clearest water of the itinerary, with a guide in it. The other: the same water, admired from land, at no charge.","by":"seed"},{"t":"p","text":"The case for each side was heard in full. On cobbles. In the sun.","by":"seed"},{"t":"mono","text":"Revellata snorkel, optional, EUR 150 pp, resolution not recorded","by":"seed"},{"t":"prompt","q":"Snorkel taken or declined, and on what grounds?","by":"seed"},{"t":"card","star":"Walls first out of the water, both eyes still ours","lines":[],"by":"seed"}]', '["drops","water","hardship"]', 'still no rescue', 0, 70);
INSERT OR IGNORE INTO journal_chapters (id, day_date, title, voice, body, threads, closer, public, sort) VALUES ('ch07-cap-corse', '2026-08-21', 'Around Cap Corse', 'the gulf, the cap, the wine nobody planned', '[{"t":"map","focus":"saint-florent","by":"seed"},{"t":"p","text":"No lanyards. Not one, all day. Saint-Florent was the day the paperwork ran out.","by":"seed"},{"t":"p","text":"No connections to defend. No barriers to hold. Just the town around its little port, and the gulf lying there all morning, entirely unsupervised.","by":"seed"},{"t":"p","text":"Conditions in the gulf remained grim.","by":"seed"},{"t":"prompt","q":"What colour was the gulf, honestly?","by":"seed"},{"t":"drop","text":"Cap Corse is the island''s finger, pointed at Genoa. Genoa has had several hundred years to think about why.","by":"seed"},{"t":"p","text":"The run around the cap went villages, then water, then villages. Each one folded into its own slot of coast as if the last one hadn''t happened. We endured the better part of a day of this and had nothing to show for it but the day.","by":"seed"},{"t":"prompt","q":"What was the best thing on Cap Corse nobody had planned?","by":"seed"},{"t":"prompt","q":"Did a Patrimonio glass happen, and where?","by":"seed"},{"t":"card","star":"the gulf, on attendance alone","lines":[],"by":"seed"}]', '["water","drops","hardship"]', 'rations holding', 0, 80);
INSERT OR IGNORE INTO journal_chapters (id, day_date, title, voice, body, threads, closer, public, sort) VALUES ('ch08-three-hundred-days', '2026-08-22', 'Three Hundred Days', 'the emperor''s villa, included', '[{"t":"map","focus":"portoferraio","by":"seed"},{"t":"mono","text":"shore excursion — included — Napoleon''s villa, Portoferraio","by":"seed"},{"t":"p","text":"Napoleon''s villa is not big enough. That is the whole exhibit.","by":"seed"},{"t":"p","text":"Portoferraio has been catching people who didn''t entirely choose it since 1814. It caught us in the same spirit.","by":"seed"},{"t":"p","text":"Horseshoe harbour. Old town stacked behind it in the standard Italian arrangement of laundry and geraniums. Above the lot, the villa — when a town has had exactly one famous resident, it does not waste him.","by":"seed"},{"t":"p","text":"The included excursion went up the hill. The man had been running a continent the previous spring. Here was a house you could walk end to end in the time it takes to lose a tour group, gardens included.","by":"seed"},{"t":"p","text":"Plus a terrace from which he could inspect his entire jurisdiction without binoculars.","by":"seed"},{"t":"p","text":"We did the rooms at the pace the group allowed, which is the pace of the slowest photographer. The rooms held their own. Small windows, sea light, furniture built for a man planning to be elsewhere.","by":"seed"},{"t":"prompt","q":"Which object in the villa did we both stop at?","by":"seed"},{"t":"p","text":"He kept the full ceremony going while he was here. The household, the receptions, the etiquette of the Tuileries — transplanted onto an audience of one small island. Reads either as dignity or as a man declining to update his org chart.","by":"seed"},{"t":"prompt","q":"What did the guide skip that the book wouldn''t have?","by":"seed"},{"t":"drop","text":"Three hundred days. He rebuilt the roads, reorganised the iron mines, drafted a constitution — on an island he could see the whole of from his terrace. So what would we get done with three hundred days and no meetings?","by":"seed"},{"t":"drop","text":"He gave the island a flag before he gave it anything else. White, one red stripe, three golden bees. What does a man fix on day one, and what does that tell you?","by":"seed"},{"t":"doctrine","text":"\"Deferral is fine. Deferral without a rebooking date is Elba.\"","by":"seed"},{"t":"drop","text":"26 February 1815. Out of this exact harbour, back towards the whole catastrophe, entirely of his own accord. How long had he been watching the water?","by":"seed"},{"t":"p","text":"The afternoon was ours once the villa was done. Elba in the afternoon is the kind of hardship it would be indelicate to describe to people back home.","by":"seed"},{"t":"prompt","q":"Did we swim on Elba, and where?","by":"seed"},{"t":"p","text":"We sailed the same evening. An exit it took him three hundred days to organise.","by":"seed"}]', '["drops","doctrine","hardship"]', 'no word from Paris', 0, 90);
INSERT OR IGNORE INTO journal_chapters (id, day_date, title, voice, body, threads, closer, public, sort) VALUES ('ch09-arrival-by-water', '2026-08-23', 'Arrival by Water', 'a private boat, Santa Margherita, Rapallo, the kayak question', '[{"t":"map","focus":"portofino","by":"seed"},{"t":"p","text":"A launch turned up. Included.","by":"seed"},{"t":"p","text":"The boat day was the included one — the clause you skim at booking. Then a launch arrives and the clause means exactly what it said. Santa Margherita, Rapallo, Portofino, the whole run from the water, which is the side that coast was drawn from in the first place.","by":"seed"},{"t":"mono","text":"launch: included. the only line of the week with nothing in the amount column, a category of transaction I don''t fully trust.","by":"seed"},{"t":"p","text":"One open item: the kayak. A hundred and ten a head to move under your own power across water we were already being carried over in comfort. Either the best money on the coast or the silliest — I could argue both sides.","by":"seed"},{"t":"ledger","amount":"110 EUR pp","text":"the kayak question, resolution unrecorded.","by":"seed"},{"t":"prompt","q":"Kayak — taken or declined, and on what grounds?","by":"seed"},{"t":"p","text":"Santa Margherita and Rapallo split the middle of the day. An hour ashore between them. The record is silent on how it was divided.","by":"seed"},{"t":"prompt","q":"Santa Margherita or Rapallo: which got the hour?","by":"seed"},{"t":"p","text":"We had been arriving at places off the water all trip, one way and another. This was the first day built around nothing else.","by":"seed"},{"t":"p","text":"Portofino came at the end of the run. The right end for it. By road it is a queue behind a bus on a lane cut for carts.","by":"seed"},{"t":"p","text":"By sea the harbour simply opens. The houses stand around it with their good paint facing out — nobody who built that place expected you to come any other way. We came in the front door.","by":"seed"},{"t":"prompt","q":"What did Portofino look like from the water on the way in?","by":"seed"},{"t":"drop","text":"Every house on that coast keeps its best paint on the seaward wall. Who were they dressed for, before the ferries?","by":"seed"},{"t":"p","text":"A difficult day on the water, all told. Somebody had to have it.","by":"seed"}]', '["water","ledger","drops"]', 'somehow we endure', 0, 100);
INSERT OR IGNORE INTO journal_chapters (id, day_date, title, voice, body, threads, closer, public, sort) VALUES ('ch10-the-lily', '2026-08-24', 'The Lily', 'granita in the port, the Giannutri question', '[{"t":"map","focus":"giglio","by":"seed"},{"t":"p","text":"Granita at the port. That is the morning''s one hard fact.","by":"seed"},{"t":"p","text":"Giglio does its mornings at the harbour — a curve of coloured houses around the boats, not much else. An island that size has already decided where you''ll be standing. We didn''t argue.","by":"seed"},{"t":"p","text":"The rest of the detail has gone wherever mornings go.","by":"seed"},{"t":"prompt","q":"Where was the granita and what flavour?","by":"seed"},{"t":"p","text":"Giannutri sat out there the whole time. A smaller island, an hour off the bow, the open question. We had done the deciding in advance — decided how we would decide, then declined to reopen the file. Per the rules.","by":"seed"},{"t":"doctrine","text":"\"Rule 5: the switch criterion is decided at the fork, once.\"","by":"seed"},{"t":"prompt","q":"Did the Giannutri boat happen?","by":"seed"},{"t":"p","text":"Either way, the water off Giglio Porto runs past Le Scole. A low line of rocks just south of the harbour mouth. Every boat that comes or goes passes them.","by":"seed"},{"t":"drop","text":"Le Scole is where the Costa Concordia went onto the rocks on the night of 13 January 2012. Thirty-two people died. Taking the ship off the island afterwards became the largest maritime salvage in history.","by":"seed"},{"t":"prompt","q":"What was said, if anything, passing Le Scole?","by":"seed"},{"t":"p","text":"The rocks are just rocks again. The water over them is the same water as everywhere else on that coast. That''s the island''s answer to the whole business, and probably the right one.","by":"seed"},{"t":"p","text":"They call Giglio the lily. Apparently the name comes from an old Greek word to do with goats, not the flower. The island has clearly decided not to pursue the matter — by mid-morning that struck us as sound policy.","by":"seed"},{"t":"card","star":"granita at the port, flavour under investigation","lines":[],"by":"seed"}]', '["water","drops","doctrine"]', 'the hardship continues', 0, 110);
INSERT OR IGNORE INTO journal_chapters (id, day_date, title, voice, body, threads, closer, public, sort) VALUES ('ch11-where-the-painter-stopped', '2026-08-25', 'Where the Painter Stopped', 'the Spanish built the forts; a painter died running past them', '[{"t":"map","focus":"porto-ercole","by":"seed"},{"t":"p","text":"Three Spanish forts, one fishing harbour. That is a lot of masonry per boat.","by":"seed"},{"t":"p","text":"This coast was the Presidi once, and the forts tell you what the Spaniards thought of their neighbours. They still stand over the town at exactly the angle their engineers chose to discourage visitors. We went up anyway. Discouraging visitors is all they do for a living now.","by":"seed"},{"t":"prompt","q":"Which fort got climbed and which got skipped?","by":"seed"},{"t":"p","text":"Below all that defence: the usual Argentario blue. The kind that makes hardship reporting difficult to file with a straight face. There was also a beach, which is the whole problem with this stretch of Italy.","by":"seed"},{"t":"prompt","q":"Any swim, or was the beach the view?","by":"seed"},{"t":"doctrine","text":"Conditions remain grim.","by":"seed"},{"t":"p","text":"Somewhere in the middle there was lunch. There always is. The paperwork on it is thin.","by":"seed"},{"t":"prompt","q":"What was lunch and who found it?","by":"seed"},{"t":"p","text":"The reason Porto Ercole is in this book at all: this is where Caravaggio stopped. July 1610, the pardon finally arranged — and the pardon and the paintings both on a felucca that had sailed without him. So he chased it. Up this coast, on foot, in that month, in that heat. He was thirty-eight.","by":"seed"},{"t":"p","text":"He got exactly as far as Porto Ercole. On the 18th of July he was done. The felucca does not appear to have noticed.","by":"seed"},{"t":"drop","text":"A man running out of coastline, the boat holding its line. Was he chasing the paintings or the pardon?","by":"seed"},{"t":"p","text":"The town kept the grave. It is up there somewhere still, filed under a name nobody could spell. The paintings kept the water. That part of the story was not finished at Porto Ercole. Neither are we with it.","by":"seed"},{"t":"card","star":"Porto Ercole, the town that stopped Caravaggio","lines":[],"by":"seed"}]', '["drops","water","hardship"]', 'no improvement to report', 0, 120);
INSERT OR IGNORE INTO journal_chapters (id, day_date, title, voice, body, threads, closer, public, sort) VALUES ('ch12-at-sea', '2026-08-26', 'At Sea', 'no port, no plan, a volcano possibly at dinner', '[{"t":"map","focus":"porto-ercole--lipari","by":"seed"},{"t":"p","text":"We woke to nothing. No port, no tender times, no meeting point, no man with a clipboard. Water in every direction.","by":"seed"},{"t":"p","text":"Overnight out of Porto Ercole, and the first day of the whole run with nothing on it. The day just stood there, empty, asking what I intended to do about it.","by":"seed"},{"t":"p","text":"So the ship stopped carrying us between places and became the place. Same decks, same rotation, the sea going past at a speed nobody could verify. No plan to execute, no way to fall behind one — which, for a man who runs on a schedule, was grim.","by":"seed"},{"t":"drop","text":"The wake was the only evidence we were getting anywhere. How fast does a ship need to go before you stop checking?","by":"seed"},{"t":"prompt","q":"What actually filled the hours between breakfast and the horizon watch?","by":"seed"},{"t":"p","text":"Somewhere in the middle of all that nothing, it landed: this was the last piece of pure infrastructure on the whole trip. Steel, timetables, staff whose lanyards mean what they say.","by":"seed"},{"t":"p","text":"From Sicily on, we were being handed over to people. People, unlike ships, do not publish schedules.","by":"seed"},{"t":"doctrine","text":"\"The pause is part of the plan.\"","by":"seed"},{"t":"p","text":"A day with nothing in it still gets a card in this family. Claire''s card is hers to write. I kept my speculation to myself, which is not the same as not having any.","by":"seed"},{"t":"prompt","q":"What was Claire''s star for the sea day?","by":"seed"},{"t":"p","text":"By evening: the rail, the horizon watch, the Aeolians somewhere ahead in the dark. Off to the south, a thin line of smoke may have been standing up off the water — Stromboli, keeping its fire going. Or cloud doing a reasonable impression of one.","by":"seed"},{"t":"p","text":"The light was going. I have declined to rule on it.","by":"seed"},{"t":"drop","text":"A mountain that has been burning since before there were countries, filed by the shipping lanes under navigation aids. What else out there works that hard to be taken for granted?","by":"seed"},{"t":"prompt","q":"Did Stromboli smoke?","by":"seed"}]', '["doctrine","drops","hardship"]', 'we soldier on', 0, 130);
INSERT OR IGNORE INTO journal_chapters (id, day_date, title, voice, body, threads, closer, public, sort) VALUES ('ch13-obsidian', '2026-08-27', 'Obsidian', 'the Aeolians, up close', '[{"t":"map","focus":"lipari","by":"seed"},{"t":"p","text":"There''s a castle on a rock in the middle of town. That''s where you put one when six thousand years of neighbours keep arriving by boat.","by":"seed"},{"t":"p","text":"Lipari is the big one — in the Aeolians, a relative term. The town runs between two harbours. The day began in the port. On Lipari everything does. The island is arranged around its harbour the way an office is arranged around the kettle.","by":"seed"},{"t":"prompt","q":"How did we get around the island — and what did it cost, agreed when?","by":"seed"},{"t":"drop","text":"For about four thousand years the sharpest edge in the known world came off this island, and half the Neolithic Mediterranean carried a flake of Lipari black in its kit. Silicon Valley, same margins, better weather.","by":"seed"},{"t":"p","text":"The north end is pumice country. Whole hillsides quarried and shipped by the sack, until UNESCO suggested they stop selling the scenery.","by":"seed"},{"t":"p","text":"Below the old workings the seabed is white. The water over it is the colour the brochures are always lying about. Except here.","by":"seed"},{"t":"drop","text":"Pumice is the stone that floats. They dug up a mountain here light enough to swim home.","by":"seed"},{"t":"prompt","q":"Where was lunch, and what story did the table produce?","by":"seed"},{"t":"p","text":"The afternoon belonged to the water. Standing arrangement on this leg. Not renegotiated.","by":"seed"},{"t":"prompt","q":"Did anyone jump off anything?","by":"seed"},{"t":"drop","text":"Homer put Aeolus on these islands — every bad wind handed to Odysseus tied in one bag. The crew opened it within sight of Ithaca. Who opens the bag in this family?","by":"seed"},{"t":"p","text":"By evening the harbour had refilled. The volcanoes were still queueing along the horizon. I regret to report conditions had not improved.","by":"seed"},{"t":"card","star":"the water, again, which keeps winning these","lines":[],"by":"seed"}]', '["drops","water","ledger"]', 'no end in sight', 0, 140);
INSERT OR IGNORE INTO journal_chapters (id, day_date, title, voice, body, threads, closer, public, sort) VALUES ('ch14-the-volcano-upstage', '2026-08-28', 'The Volcano Upstage', 'Giardini Naxos in, granita at Bam Bar, the last night at sea', '[{"t":"map","focus":"taormina","by":"seed"},{"t":"p","text":"The Greeks aimed a theatre at a volcano. It''s still in the cast.","by":"seed"},{"t":"p","text":"The tender put us in at Giardini Naxos — first Greek landing in Sicily, two and a half thousand years before ours. So the anchorage came recommended. From there the only direction on offer is up.","by":"seed"},{"t":"p","text":"Taormina sits on a shelf of hill with a clear view of everything and a clear intention of not being easily visited. We overruled it.","by":"seed"},{"t":"p","text":"The theatre is what the climb is for. The Greeks cut it into the ridge and pointed the stage straight at Etna. The largest volcano in Europe, hired as scenery. Never missed a performance.","by":"seed"},{"t":"p","text":"One note for certain members of the touring party. The venue contains no screens. Never has. Sold out for centuries regardless.","by":"seed"},{"t":"prompt","q":"Was Etna doing anything behind the stage?","by":"seed"},{"t":"drop","text":"They built the seats before they hired the actors. Aimed the whole thing at the scenery. What else were they pointing their buildings at?","by":"seed"},{"t":"p","text":"Down in the town the true institution is not the theatre. It is Bam Bar, which does granita and has correctly concluded that nothing further is required of it. You don''t need to read a review — the queue is the review, published daily on the footpath, rigorously refereed.","by":"seed"},{"t":"p","text":"We joined it. Conditions were grim. Only granita was going to address them.","by":"seed"},{"t":"prompt","q":"What granita, in what order?","by":"seed"},{"t":"card","star":"Bam Bar, where the queue wrote the review and the granita signed it.","lines":[],"by":"seed"},{"t":"p","text":"That was the last night on board.","by":"seed"},{"t":"prompt","q":"What was the last-night table like?","by":"seed"}]', '["drops","screens","hardship"]', 'grim, as forecast', 0, 150);
INSERT OR IGNORE INTO journal_chapters (id, day_date, title, voice, body, threads, closer, public, sort) VALUES ('ch15-the-knights-city', '2026-08-29', 'The Knights'' City', 'disembark 08:00; the only painting he ever signed', '[{"t":"map","focus":"valletta","by":"seed"},{"t":"p","text":"Off the ship at 08:00. Valletta''s first move is uphill. After ten nights of lifts and buffets, the party received this as a provocation.","by":"seed"},{"t":"p","text":"The Knights built the place in a hurry after nearly losing the whole island, and it shows. Everything is a fortress, including a fair proportion of the churches. The streets run straight down to the harbour so the sea can see exactly what it is dealing with.","by":"seed"},{"t":"p","text":"We had been following Caravaggio around the Mediterranean like creditors. Valletta is where the trail ends. The Oratory of St John''s holds the Beheading — the biggest thing he ever painted, and the only one he ever signed.","by":"seed"},{"t":"drop","text":"The signature is in the blood running from the Baptist''s throat. f. Michelangelo — the one time in his life he put his name to a canvas. What does a man mean by signing there?","by":"seed"},{"t":"p","text":"I was not ready for it. We stood in front of it. I have no joke about it.","by":"seed"},{"t":"prompt","q":"How long did we stand in front of the Beheading?","by":"seed"},{"t":"p","text":"At twelve the Saluting Battery fires its gun, whether you have arrived or not. The sound goes around the Grand Harbour and comes back with interest. The harbour has been tolerating this since the Knights ran the place.","by":"seed"},{"t":"drop","text":"A cannon that exists so ships could set their chronometers by it. Who still sets anything by a cannon?","by":"seed"},{"t":"prompt","q":"Did we make the noon gun or hear it from somewhere else?","by":"seed"},{"t":"p","text":"The 1926 had a premium suite with our name on it and breakfast attached. After ten nights in a cabin, this was ruled adequate compensation for the hills. The ruling was not unanimous until the door actually opened.","by":"seed"},{"t":"mono","text":"1926 La Galerie Art Suites — conf 73521701309804","by":"seed"},{"t":"ledger","amount":"450 AUD","text":"the 1926, premium suite, breakfast","by":"seed"},{"t":"prompt","q":"What was the room like after ten nights afloat?","by":"seed"},{"t":"p","text":"Conditions ashore, it was agreed, remained grim.","by":"seed"}]', '["drops","ledger","hardship"]', 'the siege continues', 0, 160);
INSERT OR IGNORE INTO journal_chapters (id, day_date, title, voice, body, threads, closer, public, sort) VALUES ('ch16-slow-malta', '2026-08-30', 'Slow Malta', 'Mdina says nothing; St Peter''s Pool asks one question', '[{"t":"map","focus":"valletta","by":"seed"},{"t":"p","text":"Mdina calls itself the Silent City. I audited the claim. It held up.","by":"seed"},{"t":"p","text":"A walled town on a hill that stopped mattering around 1565 and has declined to comment since. Streets a horse-width across. Limestone the colour of the hour. Door knockers above eye level, for people who no longer answer.","by":"seed"},{"t":"p","text":"Every other place on this trip had spent the day explaining itself at us. Here was a whole city with nothing to add. We walked it at the pace it asked for and added nothing either.","by":"seed"},{"t":"prompt","q":"What did Mdina sound like?","by":"seed"},{"t":"p","text":"Back at the Grand Harbour we crossed to the Three Cities by dghajsa — a gondola with a proper job. You sit at water level in a painted boat, on a channel that has moved somebody''s cargo since before the Phoenicians invented the receipt.","by":"seed"},{"t":"p","text":"The Knights ran their fleet out of these creeks. Then the Royal Navy. Now the same water carries tourists at the same unhurried angle. As career changes go, not the worst.","by":"seed"},{"t":"prompt","q":"What did the dghajsa boatman talk about?","by":"seed"},{"t":"drop","text":"Maltese is the last living branch of Siculo-Arabic, and the most Catholic country in Europe says its prayers to Alla. What does a language keep that its speakers have agreed not to mention?","by":"seed"},{"t":"p","text":"Then out along the coast to St Peter''s Pool. Not a pool. A shelf of pale rock the sea has cut into the shape of a decision.","by":"seed"},{"t":"p","text":"Flat stone, clear water, a drop of a few metres. The place asks everyone on the edge exactly one question. It is a very old question, and the rock is neutral — it has watched people answer both ways for as long as there have been feet.","by":"seed"},{"t":"p","text":"We stood there a while, the water doing its colours below us.","by":"seed"},{"t":"prompt","q":"Did anyone jump at St Peter''s Pool?","by":"seed"},{"t":"card","star":"the dghajsa across the Grand Harbour, sitting at water level in a boat older than the idea of hurrying","lines":[],"by":"seed"}]', '["water","drops","trade-channel"]', 'conditions remain grim', 0, 170);
INSERT OR IGNORE INTO journal_chapters (id, day_date, title, voice, body, threads, closer, public, sort) VALUES ('ch17-the-crossing', '2026-08-31', 'The Crossing', 'the biggest fast cat in the Med, then 230 kilometres of Sicily', '[{"t":"map","focus":"pozzallo","by":"seed"},{"t":"p","text":"Two countries in one day. No airport involved.","by":"seed"},{"t":"p","text":"The St John Paul II left Valletta at 07:30. Virtu are firm on the point that she is the largest high-speed catamaran in the Mediterranean. That is the sort of fact a boat leads with when it would rather you thought about size than movement.","by":"seed"},{"t":"p","text":"An hour and three quarters of open water, most of it before nine. Pozzallo at 09:15. As ports go, less a destination than a thing ferries admit to on the way past.","by":"seed"},{"t":"mono","text":"Virtu Ferries, St John Paul II, 07:30 Valletta–Pozzallo, ref 10729224","by":"seed"},{"t":"ledger","amount":"unrecorded","text":"the ferry pair, two seats on the largest high-speed catamaran in the Med","by":"seed"},{"t":"prompt","q":"Was the crossing smooth, and did anyone regret breakfast?","by":"seed"},{"t":"p","text":"The land side went to the trade channel. One car, one driver, 230 kilometres from the bottom-right corner of the island to the top-left. The quotes came back between €280 and €380 — a hundred euros of daylight on the same road, with the same amount of Sicily in the middle.","by":"seed"},{"t":"prompt","q":"Which driver quote won, and how was it found?","by":"seed"},{"t":"ledger","amount":"280-380 EUR","text":"the driver, quote range, winner unrecorded","by":"seed"},{"t":"p","text":"Whoever won carried us through the interior. The part the postcards skip. Wheat, distance, towns up on their hills watching the road go by without much interest.","by":"seed"},{"t":"p","text":"By early afternoon, Villa Igiea. Started the day in one country, finished the drive in another, a sea in between. The correct way to do it, and almost never the way it gets done.","by":"seed"},{"t":"drop","text":"Two seas in one day — the one crossed, the one arrived beside. Did anyone clock the moment the water changed sides?","by":"seed"},{"t":"prompt","q":"What was the 230 kilometres like from the back seat?","by":"seed"},{"t":"card","star":"230 kilometres of interior Sicily survived from the back seat","lines":[],"by":"seed"},{"t":"p","text":"Aurora''s train got in from Rome that night. She''d sat an exam that morning. Palermo could wait an evening.","by":"seed"}]', '["trade-channel","ledger","water"]', 'the hardship continues', 0, 180);
INSERT OR IGNORE INTO journal_chapters (id, day_date, title, voice, body, threads, closer, public, sort) VALUES ('ch18-lunch-at-one', '2026-09-01', 'Lunch at One', 'her city, her table, possibly her parents', '[{"t":"map","focus":"palermo","by":"seed"},{"t":"mono","text":"01 SEP · PALERMO · LUNCH 13:00 — no ref, no confirmation email, no cancellation policy","by":"seed"},{"t":"p","text":"Lunch. Palermo. One o''clock or thereabouts. That was the entire entry.","by":"seed"},{"t":"p","text":"By the first of September the trip was a folder of PDFs — flights, rooms, transfers, every line with its reference number and its cancellation window. Except one. The one the whole day was built around.","by":"seed"},{"t":"p","text":"It never appeared on any platform. No card ever held it. It moved through the trade channel or it did not move at all, and the trade channel had delivered.","by":"seed"},{"t":"doctrine","text":"\"You can book a table anywhere in the world. You can''t book being taken to one.\"","by":"seed"},{"t":"p","text":"Aurora picked the place. A local choosing the room is the last screen you ever need. We asked for no further details and were given none.","by":"seed"},{"t":"prompt","q":"Where did she take us?","by":"seed"},{"t":"p","text":"The register said possibly her parents. That is the kind of possibly you iron a shirt for. On that subject the paperwork stayed silent.","by":"seed"},{"t":"prompt","q":"Were the parents there — and what was that like?","by":"seed"},{"t":"p","text":"The bookings could only give me the shape of it. A table filled at one, Sicily, September, conditions presumably grim. The afternoon cancelled in advance with nothing scheduled against it — which cost me more discipline than it cost Claire.","by":"seed"},{"t":"p","text":"Past one o''clock the record goes quiet. It does not pick up again until well into the afternoon. That is how you know it was a proper table.","by":"seed"},{"t":"prompt","q":"Which dish did the table go quiet for?","by":"seed"},{"t":"p","text":"Nothing to confirm. Nothing to cancel. Nothing to claim back. The best-performing asset on the itinerary, and it never touched the ledger.","by":"seed"},{"t":"ledger","amount":"0.00 EUR","text":"a table at one, the only line on the trip money couldn''t reach","by":"seed"},{"t":"drop","text":"One line in the folder with no reference number on it. How many of those does a trip need before it counts as a good one?","by":"seed"},{"t":"card","star":"Lunch at one, her room, her call.","lines":[],"by":"seed"}]', '["trade-channel","screens","hardship"]', 'conditions remain grim', 0, 190);
INSERT OR IGNORE INTO journal_chapters (id, day_date, title, voice, body, threads, closer, public, sort) VALUES ('ch19-gold-in-the-morning', '2026-09-02', 'Gold in the Morning', 'mosaics before the heat, Ballarò before lunch, the pool before the last dinner', '[{"t":"map","focus":"palermo","by":"seed"},{"t":"p","text":"The ceiling switched itself on. Acres of gold mosaic, depending on whose survey you trust. Every surface employed.","by":"seed"},{"t":"p","text":"That was Monreale, Wednesday, up the hill before the heat had properly reported for duty — the only hour that town receives visitors on fair terms. William II ran the cathedral up in the 1170s, largely to annoy the Archbishop of Palermo. You come in out of the white glare of the square and the whole thing reads like a ledger that only ever recorded credits.","by":"seed"},{"t":"drop","text":"Somewhere in the nave William hands the finished church up to the Virgin. He is holding the entire building in his two hands, like a model. What would you build, at twenty-two, if nobody could stop you?","by":"seed"},{"t":"prompt","q":"What did Claire say inside Monreale?","by":"seed"},{"t":"p","text":"Then back down into Ballarò. Full voice by mid-morning — the market''s only setting. We let it carry us through, on the theory that the last morning is the one where you finally buy the things you have been circling all week.","by":"seed"},{"t":"prompt","q":"What came home from Ballarò?","by":"seed"},{"t":"p","text":"The afternoon was assigned to the Villa Igiea pool. I want it minuted that we endured it. The water held its temperature without apology, and the sea lay flat beyond the balustrade, doing nothing to help.","by":"seed"},{"t":"p","text":"Hour after hour, we bore it. Nobody packed so much as a sock — the flight wasn''t until Thursday midday, and a bag half-zipped on a Wednesday is a sign of weakness.","by":"seed"},{"t":"p","text":"Conditions, in short, remained grim to the end.","by":"seed"},{"t":"p","text":"There was one last dinner. The grand kind, the sort Sicily had been auditioning for all fortnight. It went long, as the last one is contractually required to.","by":"seed"},{"t":"prompt","q":"Where was the last dinner, and what was the toast?","by":"seed"},{"t":"card","star":"Proposed: the gold, obviously, though the pool put up a late and unwelcome case.","lines":[],"by":"seed"}]', '["drops","water","hardship"]', 'the ordeal nears its end', 0, 200);
INSERT OR IGNORE INTO journal_chapters (id, day_date, title, voice, body, threads, closer, public, sort) VALUES ('ch20-the-long-way-home', '2026-09-03', 'The Long Way Home', 'BA619, a lounge, QF2, Saturday morning somewhere', '[{"t":"map","focus":"palermo","by":"seed"},{"t":"p","text":"Nothing had gone wrong yet. I would like that noted for the file.","by":"seed"},{"t":"p","text":"This one I wrote off the confirmation emails, on the third of September — the only chapter that''s all paperwork. The paperwork said BA619 out of Palermo at 12:05, Heathrow at 14:20. Then six and a half hours of Terminal 3 before QF2 at 20:50, the bulk of it to be served in the First lounge, where conditions are historically grim.","by":"seed"},{"t":"mono","text":"BA619 PMO–LHR 12:05 → 14:20 · QF2 LHR–SYD dep 20:50 · Premium Flex","by":"seed"},{"t":"p","text":"QF2 had been the Wednesday until it wasn''t. That is what Premium Flex is for. You buy the fare knowing the plan will move, then you let it move.","by":"seed"},{"t":"p","text":"One piece was still in the air: the bid for the front cabin, sitting in a Qantas machine somewhere, marked pending. Pending is where this chapter has to leave it.","by":"seed"},{"t":"prompt","q":"Did the F bid land?","by":"seed"},{"t":"p","text":"An afternoon is a long tenancy in a lounge, even that one. I had it pencilled in as the trip''s last stretch of proper hardship — six hours of other people''s hospitality between us and the gate. None of what actually happened in there made it into any email.","by":"seed"},{"t":"prompt","q":"What was the lounge''s one contribution to the trip?","by":"seed"},{"t":"p","text":"The bookings ended the way bookings always do. Cleanly. No weather, no lanyards, no one-minute margins.","by":"seed"},{"t":"p","text":"QF2 down in Sydney on the Saturday morning, the whole thing behind us. That is where the paperwork stops.","by":"seed"},{"t":"prompt","q":"First thing said on the ground in Sydney?","by":"seed"},{"t":"p","text":"Which leaves the books. Somebody in this family was always going to keep them.","by":"seed"},{"t":"ledger","amount":"981 GBP","text":"Eurostar, the 13:31 out of St Pancras","by":"seed"},{"t":"ledger","amount":"148 EUR","text":"the 19:00 to Lyon, bought at 18:16","by":"seed"},{"t":"ledger","amount":"880 AUD","text":"Hotel Suisse","by":"seed"},{"t":"ledger","amount":"23,280 AUD","text":"the ship","by":"seed"},{"t":"ledger","amount":"450 AUD","text":"the 1926","by":"seed"},{"t":"ledger","amount":"unrecorded","text":"the ferry pair","by":"seed"},{"t":"ledger","amount":"unrecorded","text":"the driver","by":"seed"},{"t":"doctrine","text":"The plan is a doctrine, not an itinerary; the best assets can''t be booked, only introduced.","by":"seed"}]', '["ledger","doctrine","hardship"]', 'the hardship continues, now at altitude', 0, 210);
INSERT OR IGNORE INTO journal_meta (id, json) VALUES ('prompts', '{"ch00-two-pints":["Which pub, and whose pint was the map drawn on?","What did the upgrade actually buy — the seat or the sleep?","What was the first port either of us said out loud?"],"ch01-gare-du-nord":["What did the lanyard actually look like?","What was said to the two behind us, and in which language?","What went into the pré-plainte as evidence?"],"ch02-lyon-caught-us":["What came home from Halles Paul Bocuse and what got eaten standing up?","What was the champagne on the Fourvière terrace?","Who decided Lyon deserved the second night, and when?"],"ch03-fourteen-degrees":["Which bottle came back from the Caveau?","Where exactly were we standing when Mont Blanc got deferred?","What was the 70mm line a reply to?"],"ch04-the-1140":["What did Marseille look like from the platform?","What could you see when the shutters opened?","First dinner in Nice — where, and who chose?"],"ch05-the-last-berth":["When did we know 306 was the right cabin?","What did the €400 Virtuoso credit become?","Where were we standing when she sailed?"],"ch06-calvi":["What did Claire photograph from the tender?","What did the guide say that survived the day?","Snorkel taken or declined, and on what grounds?"],"ch07-cap-corse":["What colour was the gulf, honestly?","What was the best thing on Cap Corse nobody had planned?","Did a Patrimonio glass happen, and where?"],"ch08-three-hundred-days":["Which object in the villa did we both stop at?","What did the guide skip that the book wouldn''t have?","Did we swim on Elba, and where?"],"ch09-arrival-by-water":["Kayak — taken or declined, and on what grounds?","Santa Margherita or Rapallo: which got the hour?","What did Portofino look like from the water on the way in?"],"ch10-the-lily":["Where was the granita and what flavour?","Did the Giannutri boat happen?","What was said, if anything, passing Le Scole?"],"ch11-where-the-painter-stopped":["Which fort got climbed and which got skipped?","Any swim, or was the beach the view?","What was lunch and who found it?"],"ch12-at-sea":["What actually filled the hours between breakfast and the horizon watch?","What was Claire''s star for the sea day?","Did Stromboli smoke?"],"ch13-obsidian":["How did we get around the island — and what did it cost, agreed when?","Where was lunch, and what story did the table produce?","Did anyone jump off anything?"],"ch14-the-volcano-upstage":["Was Etna doing anything behind the stage?","What granita, in what order?","What was the last-night table like?"],"ch15-the-knights-city":["How long did we stand in front of the Beheading?","Did we make the noon gun or hear it from somewhere else?","What was the room like after ten nights afloat?"],"ch16-slow-malta":["What did Mdina sound like?","What did the dghajsa boatman talk about?","Did anyone jump at St Peter''s Pool?"],"ch17-the-crossing":["Was the crossing smooth, and did anyone regret breakfast?","Which driver quote won, and how was it found?","What was the 230 kilometres like from the back seat?"],"ch18-lunch-at-one":["Where did she take us?","Were the parents there — and what was that like?","Which dish did the table go quiet for?"],"ch19-gold-in-the-morning":["What did Claire say inside Monreale?","What came home from Ballarò?","Where was the last dinner, and what was the toast?"],"ch20-the-long-way-home":["Did the F bid land?","What was the lounge''s one contribution to the trip?","First thing said on the ground in Sydney?"]}');
INSERT OR IGNORE INTO journal_meta (id, json) VALUES ('v1', '{"title":"The Crossing","sub":"conditions remain grim","hero":"Twenty-one days, four countries, one attempted robbery, one unplanned city, the last berth on a small French ship, and a table in Palermo that could not be booked, only offered.","indexable":false,"threads":{"doctrine":"the plan is a doctrine, not an itinerary","screens":"how to read a room, a queue, a lanyard","trade-channel":"the best assets can''t be booked, only introduced","water":"arrival by water, swims with stories in them","drops":"one image, one question, filed by site","ledger":"every price and what it actually bought","hardship":"the family register. conditions remain grim."},"cast":["Michael & Claire — the leads","Le Dumont d’Urville — 92 staterooms, one of them ours","the three gentlemen of Gare du Nord — brief appearance, poor reviews","Aurora — Palermo. The table on the first of September was hers."]}');
INSERT OR IGNORE INTO journal_intel (id, json) VALUES ('v1', '{"doctrine":[{"n":1,"rule":"The hard deadline is a cliff. Plan to last-boat-minus-one; the final boat is the reserve. Avoid ruin, then optimise.","provenance":["ch01-gare-du-nord"],"status":"lived"},{"n":2,"rule":"Spend scarce hours on non-substitutable assets.","provenance":[],"status":"aspirational — written before the trip caught up"},{"n":3,"rule":"Highest-variance leg first, where the buffer is.","provenance":[],"status":"aspirational — written before the trip caught up"},{"n":4,"rule":"Capacity-capped early; elastic items last — they double as shock absorbers.","provenance":[],"status":"aspirational — written before the trip caught up"},{"n":5,"rule":"Pre-commit the switch criterion at the fork. Judge on behaviour, never timetables. One decision, no sunk-cost drift.","provenance":["ch01-gare-du-nord"],"status":"lived — the lanyard read as behaviour, not costume"}],"corollaries":[{"text":"best-version: never consume the degraded version of a peak experience — defer and rebook.","provenance":["ch03-fourteen-degrees"],"status":"lived — Mont Blanc, 17 Aug, \"I won''t watch cams\""},{"text":"the pré-plainte-online protocol: file the same evening, attach everything, close the loop.","provenance":["ch01-gare-du-nord"],"status":"lived"},{"text":"timetables are narrative, queues are behaviour · price agreed before boarding · said twice, echoed back, screenshot","provenance":[],"status":"aspirational — written before the trip caught up"}],"contacts":[{"name":"Virtu Ferries","ref":"10729224 / ETYWX","what":"Valletta→Pozzallo 31 Aug 07:30","status":"booked"},{"name":"1926 La Galerie","ref":"73521701309804","what":"Valletta premium suite","status":"booked"},{"name":"TGV Lyon→Nice","ref":"TKD3G6 / BL4P7Q / HPW6G9","what":"the 11:40, 18 Aug","status":"booked"},{"name":"Pozzallo drivers","ref":"quotes €280–380","what":"the 230km to Palermo","status":"open"}],"protocols":[{"name":"recap-echo-screenshot","steps":["price said twice","echoed back","screenshot"],"status":"aspirational — written before the trip caught up"}]}');
